pub fn edit(a: Str, b: Str) -> Int {
  let ca = a.chars()
  let cb = b.chars()
  let m = cb.len()
  var prev: List[Int] = range(0, m + 1)
  for i in range(0, ca.len()) {
    let ai = ca.get_or(i, "")
    var cur: List[Int] = [i + 1]
    for j in range(0, m) {
      let cost = match ai == cb.get_or(j, "") {
        true => 0,
        false => 1,
      }
      let delete_cost = prev.get_or(j + 1, 0) + 1
      let insert_cost = cur.get_or(j, 0) + 1
      let replace_cost = prev.get_or(j, 0) + cost
      cur = cur.push(delete_cost.min(insert_cost).min(replace_cost))
    }
    prev = cur
  }
  return prev.get_or(m, 0)
}
